using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering.Universal;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class BNReview {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string H=>R+"/SourceAssets/B2_DomeNetwork/";static string O=>R+"/Docs/Review/2026-11-10_B2_DomeNetwork/";static Vector3 origin=new Vector3(0,-34,0);
 static Scene Check(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_B2_Circular.unity"))throw new Exception("Saved B2 edit required");Directory.CreateDirectory(O);return s;}
 static JObject Plan()=>JObject.Parse(File.ReadAllText(H+"layout.json"));
 static Vector3 V(JToken v)=>new Vector3((float)v[0],(float)v[1],(float)v[2]);
 static void Shot(string name,Vector3 pos,Vector3 target,float fov=80){var g=new GameObject("BN_ReviewCamera"){hideFlags=HideFlags.HideAndDontSave};var c=g.AddComponent<Camera>();c.transform.position=origin+pos;c.transform.LookAt(origin+target);c.nearClipPlane=.035f;c.farClipPlane=200;c.fieldOfView=fov;c.useOcclusionCulling=false;c.GetUniversalAdditionalCameraData().renderPostProcessing=false;var rt=new RenderTexture(1440,900,24){antiAliasing=4};var old=RenderTexture.active;Texture2D tex=null;try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;tex=new Texture2D(1440,900,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1440,900),0,0);tex.Apply();File.WriteAllBytes(O+name+".png",tex.EncodeToPNG());}finally{RenderTexture.active=old;c.targetTexture=null;if(tex)UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(g);}}
 public static object Before()=>Capture("before");public static object After()=>Capture("after");
 static object Capture(string prefix){var s=Check();var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));bool on=player.activeSelf;player.SetActive(false);try{foreach(string id in new[]{"E01","E02","W02","C01","W03","N01","C02"}){var r=Plan()["rooms"].Single(v=>(string)v["id"]==id);float rad=(float)r["r"];var c=new Vector3((float)r["x"],0,-(float)r["v"]);Shot(prefix+"_"+id,c+new Vector3(-rad*.36f,1.65f,-rad*.62f),c+new Vector3(.5f,2.6f,rad*.2f));if(prefix=="after"&&(id=="E01"||id=="E02"||id=="W02"))Shot(prefix+"_"+id+"_upper",c+new Vector3(-2.2f,5.2f,3.4f),c+new Vector3(2,3.7f,0));}if(prefix=="after"){var r=Plan()["rooms"].Single(v=>(string)v["id"]=="E01");var d=r["doors"].First();var c=new Vector3((float)r["x"],0,-(float)r["v"]);var p=new Vector3((float)d["x"],3.45f,(float)d["z"]);Shot(prefix+"_E01_portal",c+p*1.01f,c+new Vector3(-3.5f,4.1f,-.8f),85);}}finally{player.SetActive(on);EditorSceneManager.OpenScene(s.path);}return new{captured=prefix};}
 public static object Routes(){var s=Check();var data=Plan();var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));var cc=player.GetComponent<CharacterController>();var old=player.transform.position;float height=cc.height;var center=cc.center;bool en=cc.enabled;var rows=new List<object>();int samples=0;try{cc.enabled=false;Physics.SyncTransforms();foreach(var r in JArray.Parse(File.ReadAllText(H+"routes.json"))){string name=(string)r["name"];string id=name.Split('_')[0];var room=data["rooms"].FirstOrDefault(v=>(string)v["id"]==id);var offset=origin+(room==null?Vector3.zero:new Vector3((float)room["x"],0,-(float)room["v"]));var ps=r["points"].Select(p=>V(p)+offset).ToArray();bool crouch=name.Contains("Portal")||name.StartsWith("T");float h=crouch?1.2f:1.8f;var issues=new List<object>();var samplePoints=new List<Vector3>();for(int j=1;j<ps.Length;j++){float len=Vector3.Distance(ps[j-1],ps[j]);int n=Mathf.Max(1,Mathf.CeilToInt(len/.18f));for(int k=0;k<n;k++)samplePoints.Add(Vector3.Lerp(ps[j-1],ps[j],(float)k/n));}samplePoints.Add(ps.Last());bool legacyStairs=name=="C02_ExistingDeckAccess";
 if(legacyStairs){for(int i=0;i<samplePoints.Count;i++){var q=samplePoints[i];if(Physics.Raycast(q+Vector3.up*.45f,Vector3.down,out var support,.85f,~0,QueryTriggerInteraction.Ignore))samplePoints[i]=new Vector3(q.x,support.point.y,q.z);}}
 foreach(var p in samplePoints){samples++;var hit=Physics.OverlapCapsule(p+Vector3.up*(legacyStairs?.62f:.35f),p+Vector3.up*(h-.28f),.28f,~0,QueryTriggerInteraction.Ignore);bool floor=Physics.Raycast(p+Vector3.up*.22f,Vector3.down,out var f,.48f,~0,QueryTriggerInteraction.Ignore);if((hit.Length>0||!floor)&&issues.Count<10)issues.Add(new{pos=new[]{p.x,p.y,p.z},floor,hits=hit.Select(v=>v.name).Distinct().ToArray()});}
 var moves=new List<object>();foreach(bool reverse in new[]{false,true}){var pp=reverse?samplePoints.AsEnumerable().Reverse().ToArray():samplePoints.ToArray();cc.enabled=false;cc.height=h;cc.center=center-Vector3.up*(height-h)*.5f;player.transform.position=pp[0]+Vector3.up*(h*.5f-cc.center.y+.035f);cc.enabled=true;Physics.SyncTransforms();bool pass=true;float miss=0,feet=0;int index=0;for(int j=1;j<pp.Length;j++){var target=pp[j];index=j;for(int k=0;k<24;k++){var d=target-player.transform.position;d.y=0;miss=d.magnitude;if(miss<.025f)break;cc.Move(d.normalized*Mathf.Min(.06f,miss)+Vector3.down*.025f);}for(int k=0;k<10;k++){if((cc.Move(Vector3.down*.035f)&CollisionFlags.Below)!=0)break;}feet=player.transform.position.y+cc.center.y-h*.5f;if(miss>.12f||Mathf.Abs(feet-target.y)>(legacyStairs?cc.stepOffset+cc.skinWidth+.04f:.25f)){pass=false;break;}}moves.Add(new{reverse,passed=pass,miss,feet,index,expected=pp[index].y,position=new[]{player.transform.position.x,player.transform.position.y,player.transform.position.z}});cc.enabled=false;}
 rows.Add(new{name,crouch,samples=samplePoints.Count,passed=issues.Count==0&&moves.All(v=>(bool)v.GetType().GetProperty("passed").GetValue(v)),issues,moves});}}
 finally{cc.enabled=false;cc.height=height;cc.center=center;player.transform.position=old;cc.enabled=en;Physics.SyncTransforms();EditorSceneManager.OpenScene(s.path);}var result=new{samples,routes=rows};File.WriteAllText(O+"routes.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
 public static object Show(){var s=Check();var g=new GameObject("BN_SceneView");g.transform.position=origin+new Vector3(84.9f,1.65f,32.7f);g.transform.LookAt(origin+new Vector3(89,2.8f,39));var view=SceneView.lastActiveSceneView??EditorWindow.GetWindow<SceneView>();view.orthographic=false;view.sceneLighting=true;view.drawGizmos=false;view.AlignViewToObject(g.transform);view.Focus();UnityEngine.Object.DestroyImmediate(g);Selection.activeGameObject=null;return "E01 lower process plant and connected upper mezzanine";}
}
